// Clean Data — flag, don't drop
const REGIONS = ['Riyadh', 'Jeddah', 'Dammam'];
const HARD_FAIL = ['bad_date', 'missing_units', 'invalid_units',
                   'missing_revenue', 'invalid_revenue', 'price_outlier'];

const toNum = (v) => {
  const s = String(v ?? '').trim().replace(/,/g, '');
  if (s === '' || /^(n\/a|na|null|nan|-)$/i.test(s)) return null;
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
};

const toISODate = (v) => {
  const s = String(v ?? '').trim();
  let iso = null, m;
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) iso = s;
  else if ((m = s.match(/^(\d{2})\/(\d{2})\/(\d{4})$/))) iso = `${m[3]}-${m[2]}-${m[1]}`;
  if (!iso) return null;
  const d = new Date(iso + 'T00:00:00Z');
  return !isNaN(d) && d.toISOString().slice(0, 10) === iso ? iso : null;
};

const median = (arr) => {
  const s = [...arr].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
};

// 1) Normalize types, standardize text, flag problems, drop exact duplicates
const seen = new Set();
const rows = [];
for (const { json: r } of $input.all()) {
  const flags = [];

  const date = toISODate(r.Date);
  if (!date) flags.push('bad_date');

  const regionKey = String(r.Region ?? '').trim().toLowerCase();
  const region = REGIONS.find((x) => x.toLowerCase() === regionKey) ?? 'Unknown';
  if (region === 'Unknown') flags.push('missing_region');

  const product = String(r.Product ?? '').trim() || 'Unknown';
  if (product === 'Unknown') flags.push('missing_product');

  let units = toNum(r.Units);
  if (units === null) flags.push('missing_units');
  else if (units <= 0) { units = null; flags.push('invalid_units'); }

  let revenue = toNum(r.Revenue);
  if (revenue === null) flags.push('missing_revenue');
  else if (revenue <= 0) { revenue = null; flags.push('invalid_revenue'); }

  const cost = toNum(r.Cost);
  if (cost === null) flags.push('missing_cost');

  const row = {
    date, month: date ? date.slice(0, 7) : null,
    region, product, category: String(r.Category ?? '').trim(),
    units, revenue, cost,
    profit: revenue !== null && cost !== null ? revenue - cost : null,
    flags,
  };

  const key = [date, region, product, row.category, units, revenue, cost].join('|');
  if (seen.has(key)) continue;
  seen.add(key);
  rows.push(row);
}

// 2) Price-consistency check against each product's median unit price
const prices = {};
for (const r of rows) {
  if (r.units && r.revenue && r.product !== 'Unknown') {
    (prices[r.product] ??= []).push(r.revenue / r.units);
  }
}
const medians = Object.fromEntries(
  Object.entries(prices).map(([p, a]) => [p, median(a)])
);

for (const r of rows) {
  const m = medians[r.product];
  if (m && r.units && r.revenue) {
    const ratio = r.revenue / r.units / m;
    if (ratio > 3 || ratio < 1 / 3) r.flags.push('price_outlier');
  }
  r.is_valid = !r.flags.some((f) => HARD_FAIL.includes(f));
}

return rows.map((r) => ({ json: r }));

// Summarize — KPIs + data-quality report (single output item)
const all = $input.all().map((i) => i.json);
const valid = all.filter((r) => r.is_valid);
const rawCount = $('Extract from File').all().length;

const sum = (a, k) => a.reduce((s, r) => s + (r[k] ?? 0), 0);
const round = (n, d = 0) => Math.round(n * 10 ** d) / 10 ** d;

// Margin uses only rows where cost is known, so missing costs don't distort it
const agg = (rows) => {
  const withCost = rows.filter((r) => r.profit !== null);
  const revenue = sum(rows, 'revenue');
  const profit = sum(withCost, 'profit');
  const revWithCost = sum(withCost, 'revenue');
  return {
    orders: rows.length,
    units: sum(rows, 'units'),
    revenue: round(revenue),
    profit: round(profit),
    margin_pct: revWithCost ? round((profit / revWithCost) * 100, 1) : null,
    avg_order_value: rows.length ? round(revenue / rows.length) : null,
  };
};

const groupBy = (rows, key) => {
  const g = {};
  for (const r of rows) (g[r[key]] ??= []).push(r);
  return Object.entries(g)
    .map(([name, rs]) => ({ name, ...agg(rs) }))
    .sort((a, b) => b.revenue - a.revenue);
};

const byMonth = groupBy(valid.filter((r) => r.month), 'month')
  .sort((a, b) => a.name.localeCompare(b.name));
byMonth.forEach((m, i) => {
  const prev = byMonth[i - 1];
  m.mom_growth_pct = prev && prev.revenue
    ? round(((m.revenue - prev.revenue) / prev.revenue) * 100, 1)
    : null;
});

const flagCounts = {};
for (const r of all) for (const f of r.flags) flagCounts[f] = (flagCounts[f] ?? 0) + 1;

const dates = valid.map((r) => r.date).filter(Boolean).sort();

const summary = {
  period: { from: dates[0], to: dates[dates.length - 1] },
  data_quality: {
    raw_rows: rawCount,
    duplicates_removed: rawCount - all.length,
    rows_after_dedup: all.length,
    valid_rows: valid.length,
    excluded_rows: all.length - valid.length,
    issues_by_type: flagCounts,
  },
  overall: agg(valid),
  by_region: groupBy(valid, 'region'),
  by_category: groupBy(valid, 'category'),
  by_product: groupBy(valid, 'product'),
  by_month: byMonth,
};

return [{ json: { summary } }];

// Build HTML — executive report (self-contained, RTL, inline SVG, no external dependencies)
const S = $('Summarize').first().json.summary;

// 1) Read and parse Claude's JSON (tolerant of code fences / extra text)
const raw = $input.first().json;
const blocks = Array.isArray(raw.content) ? raw.content : [];
let text = blocks.filter((blk) => blk.type === 'text').map((blk) => blk.text).join('\n');
if (!text) text = String(raw.text ?? raw.output ?? '');

let R;
try {
  const cleaned = text.replace(/```json|```/gi, '').trim();
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start === -1 || end === -1) throw new Error('no JSON object found');
  R = JSON.parse(cleaned.slice(start, end + 1));
} catch (e) {
  throw new Error(`Could not parse the report JSON (${e.message}). If the text looks cut off, raise Maximum Number of Tokens in Write Report. Start of output: ${text.slice(0, 200)}`);
}
const arr = (v) => (Array.isArray(v) ? v : []);
const cap = R.chart_captions ?? {};

// 2) Helpers
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const fmt = (n) => Number(n ?? 0).toLocaleString('en-US');
const M = (n) => (Number(n) / 1e6).toFixed(2) + 'M';
const AR_MONTHS = ['يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'];
const monthLabel = (ym) => AR_MONTHS[Number(ym.slice(5, 7)) - 1] ?? ym;
const label = (n) => (n === 'Unknown' ? 'غير محدد' : n);
const o = S.overall;
const dq = S.data_quality;

const columnChart = (items) => {
  const W = 720, H = 310, padT = 28, padB = 56, padX = 16;
  const max = Math.max(...items.map((d) => d.revenue), 1);
  const slot = (W - padX * 2) / items.length;
  const best = items.reduce((m, d) => (d.revenue > m.revenue ? d : m), items[0]);
  const bars = items.map((d, i) => {
    const h = ((H - padT - padB) * d.revenue) / max;
    const w = slot * 0.66;
    const x = padX + i * slot + slot * 0.17;
    const cx = x + w / 2;
    const y = H - padB - h;
    const g = d.mom_growth_pct;
    const growth = g === null || g === undefined ? '' :
      `<text x="${cx}" y="${H - 6}" text-anchor="middle" class="gr ${g >= 0 ? 'up' : 'down'}">${g > 0 ? '+' : ''}${Number(g).toFixed(1)}%</text>`;
    const fill = d.name === best.name ? 'var(--hi)' : 'var(--accent)';
    return `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="4" style="fill:${fill}"/>
<text x="${cx}" y="${y - 8}" text-anchor="middle" class="val">${M(d.revenue)}</text>
<text x="${cx}" y="${H - 26}" text-anchor="middle" class="lbl">${monthLabel(d.name)}</text>${growth}`;
  }).join('');
  return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="الإيراد الشهري">${bars}</svg>`;
};

const hBars = (items, subFn) => {
  const max = Math.max(...items.map((d) => d.revenue), 1);
  return items.map((d) => `<div class="hrow"><div>${esc(label(d.name))}</div><div class="htrack"><div class="hfill" style="width:${((d.revenue / max) * 100).toFixed(1)}%"></div></div><div class="hval">${M(d.revenue)} <span class="sub">${esc(subFn(d))}</span></div></div>`).join('');
};
const share = (d) => `${((d.revenue / o.revenue) * 100).toFixed(1)}%`;
const margin = (d) => `هامش ${Number(d.margin_pct).toFixed(1)}%`;

// 3) Content blocks
const kpis = [
  ['إجمالي الإيراد', fmt(o.revenue)],
  ['إجمالي الربح', fmt(o.profit)],
  ['هامش الربح', `${o.margin_pct}%`],
  ['عدد الطلبات', fmt(o.orders)],
  ['متوسط قيمة الطلب', fmt(o.avg_order_value)],
];
const prio = { high: ['أولوية عالية', 'p-high'], medium: ['أولوية متوسطة', 'p-med'], low: ['أولوية منخفضة', 'p-low'] };
const topProducts = S.by_product.filter((p) => p.name !== 'Unknown').slice(0, 5);
const today = new Date().toLocaleDateString('en-GB', { timeZone: 'Asia/Riyadh' });
const isoDay = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Riyadh' });

const html = `<!doctype html>
<html lang="ar" dir="rtl">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(R.title)}</title>
<style>
