*{box-sizing:border-box;-webkit-print-color-adjust:exact;print-color-adjust:exact}
body{margin:0;background:var(--bg);color:var(--ink);font-family:'Segoe UI',Tahoma,Arial,sans-serif;line-height:1.7}
.wrap{max-width:980px;margin:0 auto;padding:28px 18px 48px}
header{background:linear-gradient(135deg,#0F2E4A,#1F5F99);color:#fff;border-radius:16px;padding:28px}
header h1{margin:0 0 6px;font-size:26px}
header .meta{opacity:.85;font-size:14px}
.headline{margin-top:16px;font-size:17px;line-height:1.8}
.grid{display:grid;gap:14px}
.kpis{grid-template-columns:repeat(auto-fit,minmax(170px,1fr));margin:18px 0}
.card{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:18px 20px}
.kpi .k{color:var(--muted);font-size:13px}
.kpi .v{font-size:26px;font-weight:700;margin-top:2px}
h2{font-size:19px;margin:30px 0 12px}
