svg .val{font-size:12px;fill:var(--ink);font-weight:600}
svg .lbl{font-size:12px;fill:var(--muted)}
svg .gr{font-size:11px;font-weight:600}
svg .up{fill:var(--up)}
svg .down{fill:var(--down)}
.hrow{display:grid;grid-template-columns:110px 1fr auto;gap:10px;align-items:center;margin:10px 0;font-size:14px}
.htrack{background:#EDF1F5;border-radius:6px;height:14px;overflow:hidden}
.hfill{background:var(--accent);height:100%;border-radius:6px}
.hval{white-space:nowrap;font-weight:600}
.sub{color:var(--muted);font-weight:400;font-size:12px}
.finding{border-inline-start:4px solid var(--accent)}
.risk{border-inline-start:4px solid var(--hi)}
.finding h3,.risk h3{margin:0 0 4px;font-size:16px}
.finding p,.risk p,.rec p{margin:0;color:var(--muted);font-size:14.5px}
.rec{display:grid;gap:6px}
