.badge{display:inline-block;font-size:12px;font-weight:700;padding:2px 10px;border-radius:999px;width:fit-content}
.p-high{background:#FDE8E6;color:#8F1D16}
.p-med{background:#FFF1D6;color:#7A4B00}
.p-low{background:#E4F1E9;color:#17613A}
.dq{background:#F8FAFC}
.dq p{margin:0 0 6px;font-size:14.5px}
