@media print{body{background:#fff}.wrap{padding:0}.card,header{break-inside:avoid}h2{break-after:avoid}.two>div{break-inside:avoid}}
.two .hrow{grid-template-columns:80px 1fr}.two .hval{grid-column:2}
@media print{h2{margin:20px 0 8px}footer{margin-top:14px}}
</style>
</head>
<body><div class="wrap">
<header>
  <h1>${esc(R.title)}</h1>
  <div class="meta">الفترة: ${esc(S.period.from)} إلى ${esc(S.period.to)} · تاريخ الإصدار: ${today}</div>
  <div class="headline">${esc(R.headline)}</div>
</header>

<section class="grid kpis">
${kpis.map(([k, v]) => `<div class="card kpi"><div class="k">${k}</div><div class="v">${v}</div></div>`).join('\n')}
</section>

<h2>الإيراد الشهري</h2>
<div class="card">
  <p class="cap">${esc(cap.monthly)} (النسبة أسفل كل شهر: التغير عن الشهر السابق، والشهر الأعلى مميّز بالبرتقالي)</p>
  ${columnChart(S.by_month)}
</div>

<div class="grid two">
  <div><h2>الإيراد حسب المنطقة</h2><div class="card"><p class="cap">${esc(cap.region)}</p>${hBars(S.by_region, share)}</div></div>
  <div><h2>الإيراد حسب الفئة</h2><div class="card"><p class="cap">${esc(cap.category)}</p>${hBars(S.by_category, (d) => `${share(d)} · ${margin(d)}`)}</div></div>
</div>

<h2>أعلى 5 منتجات بالإيراد</h2>
<div class="card">${hBars(topProducts, margin)}</div>

<h2>أبرز النتائج</h2>
<div class="grid">
${arr(R.key_findings).map((f) => `<div class="card finding"><h3>${esc(f.title)}</h3><p>${esc(f.detail)}</p></div>`).join('\n')}
</div>

<h2>المخاطر</h2>
<div class="grid">
${arr(R.risks).map((r) => `<div class="card risk"><h3>${esc(r.title)}</h3><p>${esc(r.detail)}</p></div>`).join('\n')}
</div>

<h2>التوصيات</h2>
<div class="grid">
${arr(R.recommendations).map((r) => { const p = prio[r.priority] ?? prio.medium; return `<div class="card rec"><span class="badge ${p[1]}">${p[0]}</span><h3>${esc(r.action)}</h3><p>${esc(r.rationale)}</p></div>`; }).join('\n')}
</div>

<h2>جودة البيانات</h2>
<div class="card dq">
  <p>بدأ التحليل بـ ${fmt(dq.raw_rows)} سجلًا؛ أُزيل ${fmt(dq.duplicates_removed)} سجلًا مكررًا، واستُبعد ${fmt(dq.excluded_rows)} سجلًا لمشاكل في الجودة، فاعتُمد ${fmt(dq.valid_rows)} سجلًا صالحًا.</p>
  <p>${esc(R.data_quality_note)}</p>
</div>

<footer>أُنشئ هذا التقرير آليًا عبر n8n وClaude · الأرقام في البطاقات والرسوم محسوبة بالكود من البيانات المنظّفة، والنص التحليلي من إعداد النموذج</footer>
</div></body></html>`;

// 4) Return as a binary file for the next node
const fileName = `Sales_Executive_Report_${isoDay}.html`;
const binary = await this.helpers.prepareBinaryData(Buffer.from(html, 'utf8'), fileName, 'text/html');
return [{ json: { fileName, title: R.title, headline: R.headline }, binary: { data: binary } }];

// Answer Report — turns the agent's markdown answer into a printable HTML report
const question = String($('When chat message received').first().json.chatInput ?? '');
const answer = String($input.first().json.output ?? $input.first().json.text ?? '');
const S = $('Summarize').first().json.summary;

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const inline = (s) => esc(s).replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>').replace(/`([^`]+)`/g, '<code>$1</code>');

// --- markdown -> HTML (headings, tables, lists, bold, paragraphs) ---
const lines = answer.replace(/\r/g, '').split('\n');
const isTable = (l) => l.trim().startsWith('|');
const isUl = (l) => /^\s*[-*•]\s+/.test(l);
const isOl = (l) => /^\s*\d+[.)]\s+/.test(l);
const isHead = (l) => /^#{1,4}\s+/.test(l.trim());
const isHr = (l) => /^(-{3,}|\*{3,})$/.test(l.trim());
const isSpecial = (l) => isTable(l) || isUl(l) || isOl(l) || isHead(l) || isHr(l);
const cells = (r) => r.trim().replace(/^\||\|$/g, '').split('|').map((c) => c.trim());
const isSep = (r) => /^\|?[\s:|-]+\|?$/.test(r.trim()) && r.includes('-');

const out = [];
let i = 0;
while (i < lines.length) {
  const t = lines[i].trim();
  if (!t) { i++; continue; }
  if (isHr(lines[i])) { out.push('<hr>'); i++; continue; }
  if (isHead(lines[i])) {
    const m = t.match(/^(#{1,4})\s+(.*)$/);
    out.push(`<h${m[1].length <= 2 ? 2 : 3}>${inline(m[2])}</h${m[1].length <= 2 ? 2 : 3}>`);
    i++; continue;
  }
  if (isTable(lines[i])) {
    const rows = [];
    while (i < lines.length && isTable(lines[i])) { rows.push(lines[i]); i++; }
    const body = rows.filter((r) => !isSep(r)).map(cells);
    const [head, ...rest] = body;
    out.push(`<div class="tw"><table><thead><tr>${head.map((c) => `<th>${inline(c)}</th>`).join('')}</tr></thead><tbody>${rest.map((r) => `<tr>${r.map((c) => `<td>${inline(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`);
    continue;
  }
  if (isUl(lines[i]) || isOl(lines[i])) {
    const ordered = isOl(lines[i]);
    const items = [];
    while (i < lines.length && (ordered ? isOl(lines[i]) : isUl(lines[i]))) {
      items.push(lines[i].replace(/^\s*([-*•]|\d+[.)])\s+/, ''));
      i++;
    }
    const tag = ordered ? 'ol' : 'ul';
    out.push(`<${tag}>${items.map((x) => `<li>${inline(x)}</li>`).join('')}</${tag}>`);
    continue;
  }
  const para = [];
  while (i < lines.length && lines[i].trim() && !isSpecial(lines[i])) { para.push(lines[i].trim()); i++; }
  out.push(`<p>${inline(para.join(' '))}</p>`);
}

// --- timestamp (Riyadh) ---
const p = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Riyadh', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' })
  .formatToParts(new Date()).reduce((a, x) => { a[x.type] = x.value; return a; }, {});
const stamp = `${p.year}-${p.month}-${p.day}_${p.hour}${p.minute}`;
const issued = `${p.day}/${p.month}/${p.year} ${p.hour}:${p.minute}`;

const html = `<!doctype html>
<html lang="ar" dir="rtl">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>تقرير إجابة: ${esc(question).slice(0, 80)}</title>
<style>
:root{--bg:#F4F6F9;--card:#fff;--ink:#1B2733;--muted:#5B6B7A;--line:#E3E8EE;--accent:#1F5F99}
*{box-sizing:border-box;-webkit-print-color-adjust:exact;print-color-adjust:exact}
body{margin:0;background:var(--bg);color:var(--ink);font-family:'Segoe UI',Tahoma,Arial,sans-serif;line-height:1.8}
